/* Centipede Peer to Peer, LLC — Company Insurance card.
   Posted in the Company Portal, the Insurance Dashboard, and every program
   dashboard so the whole team can see the company's insurance reference
   (CEO direction, Nov 18, 2026).
   Nov 18, 2026: the CEO provided an INTERNAL REFERENCE for the company's
   policy with NEXT, policy number 081457547410. The reference states on its
   face that it is NOT a certificate of insurance and is NOT proof of
   coverage, and that it is not verified with the carrier. The official
   Certificate of Insurance is held by the CEO and is not posted here.
   Coverage details, effective/renewal dates, and claims contact are on
   file with the CEO and are not shown on this reference — nothing is
   invented here. When the official certificate is posted, this same file
   is updated and copied to every dashboard. */
window.CPP_INSURANCE = {
  status: "reference", // internal reference on file — NOT a certificate of insurance, NOT proof of coverage
  carrier: "NEXT Insurance",
  policyNumber: "081457547410",
  coverage: "On file with the CEO \u2014 not shown on this reference.",
  dates: "On file with the CEO \u2014 not shown on this reference.",
  claims: "On file with the CEO \u2014 not shown on this reference.",
  notice: "Internal reference only \u2014 this is NOT a certificate of insurance and is NOT proof of coverage. The official Certificate of Insurance is held by the CEO and is not posted here. Verify coverage directly with the carrier.",
  cardImage: "data:image/jpeg;base64,"
};
(function () {
  function esc(s) { return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
  function mount() {
    const el = document.getElementById("insurance-card");
    if (!el) return;
    const p = window.CPP_INSURANCE;
    if (p.status !== "reference") {
      el.innerHTML = '<p class="hint">Company insurance is not in place yet \u2014 quotes are being gathered (November 18, 2026). When the policy is bound, the insurance card will be posted here for the whole team: the company name, the policy number, what it covers, and how to contact the company to file a claim.</p>';
      return;
    }
    el.innerHTML =
      `<p><strong>${esc(p.notice)}</strong></p>` +
      (p.cardImage ? `<p><img src="${p.cardImage}" alt="Company insurance internal reference \u2014 NEXT, policy 081457547410 (not a certificate of insurance)" style="max-width:100%;border:1px solid #ccc;border-radius:8px;"></p>` : "") +
      `<p><strong>${esc(p.carrier)}</strong><br>` +
      `<span class="hint">Policy number:</span> <strong>${esc(p.policyNumber)}</strong><br>` +
      `<span class="hint">Coverage:</span> ${esc(p.coverage)}<br>` +
      `<span class="hint">Effective / renewal dates:</span> ${esc(p.dates)}<br>` +
      `<span class="hint">Claims contact:</span> ${esc(p.claims)}</p>` +
      `<p class="hint">${esc(p.notice)}</p>`;
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", mount); else mount();
})();
